(function(){'use strict';const key='navigator-marketing-choice-v1',params=new URLSearchParams(location.search),sources=['google','bing','linkedin','chatgpt','claude','newsletter','referral','direct','other'],mediums=['organic','cpc','social','email','referral','direct','other'],campaigns=['institutions-launch','inquiry-readiness','professional-demo','verification','none','other'];let enabled=false,choice='unset',lastView='',started=false;try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&Date.now()-saved.time<180*86400000)choice=saved.choice;}catch{}const blocked=()=>navigator.globalPrivacyControl===true||navigator.doNotTrack==='1';function option(v,list,fallback){return list.includes(v)?v:fallback}function source(){const explicit=params.get('utm_source');if(explicit)return option(explicit.toLowerCase(),sources,'other');let host='';try{host=new URL(document.referrer).hostname.toLowerCase()}catch{}if(/(^|\.)google\./.test(host))return 'google';if(host.endsWith('bing.com'))return 'bing';if(host.endsWith('linkedin.com'))return 'linkedin';if(host==='chatgpt.com'||host==='chat.openai.com')return 'chatgpt';if(host==='claude.ai'||host==='claude.com')return 'claude';return host&&host!==location.hostname?'referral':'direct'}let attribution={source:source(),medium:option(params.get('utm_medium')||'direct',mediums,'other'),campaign:option(params.get('utm_campaign')||'none',campaigns,'other')};const attributionKey='navigator-marketing-attribution-v1';try{const saved=JSON.parse(sessionStorage.getItem(attributionKey));if(choice==='allow'&&!params.has('utm_source')&&!params.has('utm_campaign')&&saved&&Date.now()-saved.time<1800000)attribution={source:option(saved.source,sources,'other'),medium:option(saved.medium,mediums,'other'),campaign:option(saved.campaign,campaigns,'other')};}catch{}function remember(){try{if(choice==='allow'&&!blocked())sessionStorage.setItem(attributionKey,JSON.stringify({...attribution,time:Date.now()}));else sessionStorage.removeItem(attributionKey);}catch{}};function page(){const route=location.hash.slice(1).split('?')[0]||({'/institutions':'institutional','/institutions/':'institutional','/request-demonstration':'enquire'}[location.pathname])||'home';return({home:'home',institutional:'institutions',pricing:'plans','institutional/plans':'plans','plan-comparison':'plans','product-preview':'preview',enquire:'enquire'})[route]||(route.startsWith('plan-')?'plans':null)}function allowed(){return enabled&&choice==='allow'&&!blocked()}function send(event,plan='none'){const current=page();if(!allowed()||!current)return;fetch('/api/analytics',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({event,page:current,plan,consent:true,...attribution}),keepalive:true}).catch(()=>{});}function view(){const current=page();if(!current){lastView='';return}if(allowed()&&current!==lastView){lastView=current;started=false;send('page_view')}}function panel(){let el=document.getElementById('analytics-consent');if(!el){el=document.createElement('section');el.id='analytics-consent';el.className='analytics-consent';el.setAttribute('aria-label','Optional marketing analytics');el.innerHTML='<div><strong>Help us improve the website?</strong><p>Optional analytics count marketing-page views, plan interest and enquiries by campaign. No guidance answers, contact details, recordings or visitor IDs are collected. Your choice is saved in this browser. <a href="/privacy.html">Privacy details</a></p></div><div class="analytics-consent-actions"><button type="button" data-analytics-choice="decline">Decline analytics</button><button type="button" data-analytics-choice="allow">Allow analytics</button></div>';document.body.appendChild(el)}return el}function show(){const el=panel();el.hidden=false;if(!enabled){el.querySelector('strong').textContent='Marketing analytics are not enabled';el.querySelector('p').textContent='This preview does not collect marketing events.';el.querySelector('[data-analytics-choice="allow"]').hidden=true;el.querySelector('[data-analytics-choice="decline"]').textContent='Close';}else if(blocked()){el.querySelector('strong').textContent='Analytics are off';el.querySelector('p').textContent='Your browser privacy signal is being respected. No marketing events are collected.';el.querySelector('[data-analytics-choice="allow"]').hidden=true;el.querySelector('[data-analytics-choice="decline"]').textContent='Close'}}document.addEventListener('click',e=>{const settings=e.target.closest('[data-analytics-settings]');if(settings){show();return}const button=e.target.closest('[data-analytics-choice]');if(button){choice=button.dataset.analyticsChoice;try{localStorage.setItem(key,JSON.stringify({choice,time:Date.now()}))}catch{}remember();panel().hidden=true;lastView='';view();return}const link=e.target.closest('a[href]');if(!link||!page())return;const href=link.getAttribute('href'),match=href.match(/(?:[?&]plan=|#plan-)(essential|professional|advanced|institutional|enterprise|knowledge)/);if(href.includes('enquire')||href.includes('request-demonstration'))send('cta_click',match?match[1]:'none');else if(/^#plan-/.test(href))send('plan_interest',match?match[1]:'none')});document.addEventListener('change',e=>{if(e.target.id==='plan-need')send('plan_interest',option(e.target.value,['essential','professional','advanced','institutional'],'none'))});document.addEventListener('focusin',e=>{if(!started&&e.target.closest('#demonstration-brief')&&allowed()){started=true;send('enquiry_start')}});window.addEventListener('navigator:route',view);window.addEventListener('hashchange',view);window.NavigatorAnalytics={enquiryHeaders(){return allowed()?{'X-Navigator-Analytics':'yes','X-Navigator-Source':attribution.source,'X-Navigator-Medium':attribution.medium,'X-Navigator-Campaign':attribution.campaign}:{};}};fetch('/api/analytics/config').then(r=>r.json()).then(config=>{enabled=config.enabled===true;remember();if(enabled&&choice==='unset'&&!blocked())show();view()}).catch(()=>{});
})();
